"async function testSearch(companyName) {
    const url = 'https://bizno.net/?query=' + encodeURIComponent(companyName);
    console.log('Fetching:', url);
    try {
        const res = await fetch(url, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
            }
        });
        const html = await res.text();
        console.log('Response length:', html.length);

        // Bizno result items usually in <div class="titles"> or <a href="/article/...">
        const articles = [];
        const regex = /<a\s+href="(\/article\/[^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
        let match;
        while ((match = regex.exec(html)) !== null) {
            const link = match[1];
            const text = match[2].replace(/<[^>]+>/g, '').trim();
            articles.push({ link, text });
        }
        console.log('Articles found:', articles.slice(0, 10));

        // Search for 10 digit or xxx-xx-xxxxx
        const bizMatches = html.match(/\d{3}-\d{2}-\d{5}/g);
        console.log('Biz numbers found:', bizMatches);
    } catch (e) {
        console.error('Error:', e.message);
    }
}

